CREATE TABLE purchase_order_items (id UUID PRIMARY KEY, hotel_id UUID NOT NULL, branch_id UUID NOT NULL, purchase_order_id UUID NOT NULL, product_id UUID NOT NULL, quantity NUMERIC(19,4) NOT NULL CHECK(quantity>0), unit_price NUMERIC(19,4) NOT NULL CHECK(unit_price>=0), received_quantity NUMERIC(19,4) NOT NULL DEFAULT 0 CHECK(received_quantity>=0), FOREIGN KEY(purchase_order_id,hotel_id,branch_id) REFERENCES purchase_orders(id,hotel_id,branch_id), FOREIGN KEY(product_id,hotel_id) REFERENCES products(id,hotel_id), UNIQUE(id,hotel_id,branch_id));
